Object.assign(SNIP,{});PRESET_NOTES["l33"]={"Ví dụ: Ký tự không lặp đầu tiên": "Chữ cái dùng mảng đếm 26 ô: ô c − 'a'. Lượt đầu đếm, lượt sau tìm. s xuất hiện 3 lần, o 2 lần; a là ký tự đầu tiên chỉ xuất hiện một lần, ở vị trí 3.", "Ví dụ: Đếm cặp có tổng X khi có số trùng": "Các cặp có tổng 6: (1, 5) có 2 · 2 = 4 cặp, (3, 3) có C(3, 2) = 3 cặp: tổng 7. Với số 3 thứ ba (j = 4), bảng đã có hai số 3 nên cộng 2: đúng hai cặp mới.", "Ví dụ: Số giá trị khác nhau trong mỗi cửa sổ": "Vùng sáng là cửa sổ. khac chỉ đổi khi một giá trị đi từ 0 lên 1 lần hoặc từ 1 về 0 lần. Kết quả 3 4 4 3 3.", "Ví dụ: k giá trị phổ biến nhất": "Đếm: 4 xuất hiện 4 lần, 2 xuất hiện 3 lần, 1 hai lần, 3 một lần. Mẹo đổi dấu số lần để sort tăng dần cho ra số lần giảm dần, bằng nhau thì giá trị tăng dần. Kết quả 4 2.", "Lỗi: đếm trước rồi mới hỏi": "Chỉ có 2 cặp: (3, 3) ở vị trí 0, 3 và (1, 5). Nhưng chương trình in 4: với a[0] = 3, bảng đã chứa chính nó nên 3 tự ghép với 3; với a[3] = 3 cũng đếm cả chính nó. Hỏi trước rồi mới đếm."};EX_HINTS["l33"]=[["Bảng đếm chứa các giá trị đứng trước vị trí đang xét.", "Mỗi phần tử x: cộng số lần đã gặp X − x vào kết quả, rồi mới tăng đếm của x.", "Số cặp tới khoảng n²/2 = 5·10⁹: dùng long long."], ["Giữ bảng đếm của các phần tử trong cửa sổ, và biến khac là số giá trị có đếm > 0.", "Thêm x: đếm của x đi từ 0 lên 1 thì khac tăng. Bỏ y: đếm của y về 0 thì khac giảm.", "Đếm lại từ đầu cho mỗi cửa sổ tốn O(n · k)."], ["Đếm bằng bảng băm, rồi đưa mọi cặp (−số lần, giá trị) vào một vector.", "pair được so sánh theo phần tử đầu rồi phần tử sau: sort tăng dần cho số lần giảm dần, bằng nhau thì giá trị tăng dần.", "In phần tử second của k cặp đầu."]];
/* ===================== BÀI 33 · Bài toán đếm tần suất và tìm cặp có tổng cho trước ===================== */
/* Bài 33 · Bài toán đếm tần suất và tìm cặp có tổng cho trước
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR33=[{label:"Ví dụ: Ký tự không lặp đầu tiên",input:"",code:"#include <iostream>\nusing namespace std;\n\n#include <string>\n\nint dem[26];\n\nint main() {\n    string s = \"sosanhso\";\n    for (char c : s) dem[c - 'a']++;          // lượt 1: đếm\n    for (int i = 0; i < (int)s.size(); i++) { // lượt 2: tìm ký tự đầu tiên có đếm = 1\n        if (dem[s[i] - 'a'] == 1) {\n            cout << s[i] << \" \" << i << \"\\n\";\n            return 0;\n        }\n    }\n    cout << -1 << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dem"}],py:{code:"s = \"sosanhso\"\ndem = [0] * 26\nfor c in s:                         # lượt 1: đếm\n    dem[ord(c) - ord(\"a\")] += 1\nkq = -1\nfor i, c in enumerate(s):           # lượt 2: tìm ký tự đầu tiên có đếm = 1\n    if dem[ord(c) - ord(\"a\")] == 1:\n        kq = (c, i)\n        break\nprint(kq)",note:"Chữ cái dùng list đếm 26 ô: ô ord(c) − ord(\"a\"). s xuất hiện 3 lần, o 2 lần; a là ký tự đầu tiên chỉ xuất hiện một lần, ở vị trí 3. (Counter(s) cũng đếm được, nhưng list 26 ô nhanh hơn.)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = \"sosanhso\";\n        int[] dem = new int[26];\n        foreach (char c in s) dem[c - 'a']++;          // lượt 1: đếm\n        for (int i = 0; i < s.Length; i++)             // lượt 2: tìm ký tự đầu tiên có đếm = 1\n        {\n            if (dem[s[i] - 'a'] == 1)\n            {\n                Console.WriteLine(s[i] + \" \" + i);\n                return;\n            }\n        }\n        Console.WriteLine(-1);\n    }\n}"}},{label:"Ví dụ: Đếm cặp có tổng X khi có số trùng",input:"",code:"#include <iostream>\n#include <string>\n#include <unordered_map>\nusing namespace std;\n\nint main() {\n    int a[7] = {1, 5, 3, 3, 3, 5, 1};\n    int X = 6;\n    unordered_map<int, int> dem;   // dem[v]: số lần v xuất hiện ở các vị trí trước j\n    long long kq = 0;\n    for (int j = 0; j < 7; j++) {\n        if (dem.count(X - a[j])) kq += dem[X - a[j]];   // hỏi trước\n        dem[a[j]]++;                                    // đếm sau\n    }\n    cout << kq << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["j"]},{type:"cont",of:"dem"},{type:"vars",names:["kq"]}],py:{code:"a = [1, 5, 3, 3, 3, 5, 1]\nX = 6\ndem = {}           # dem[v]: số lần v xuất hiện ở các vị trí trước j\nkq = 0\nfor j in range(len(a)):\n    kq += dem.get(X - a[j], 0)          # hỏi trước\n    dem[a[j]] = dem.get(a[j], 0) + 1    # đếm sau\nprint(kq)",viz:[{type:"cells",of:"a",ptr:["j"]},{type:"cont",of:"dem",as:"dict"},{type:"vars",names:["kq"]}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 1, 5, 3, 3, 3, 5, 1 };\n        int X = 6;\n        Dictionary<int, int> dem = new Dictionary<int, int>();   // số lần v xuất hiện trước j\n        long kq = 0;\n        for (int j = 0; j < a.Length; j++)\n        {\n            kq += dem.GetValueOrDefault(X - a[j]);          // hỏi trước\n            dem[a[j]] = dem.GetValueOrDefault(a[j]) + 1;    // đếm sau\n        }\n        Console.WriteLine(kq);\n    }\n}",viz:[{type:"cells",of:"a",ptr:["j"]},{type:"cont",of:"dem",as:"dict"},{type:"vars",names:["kq"]}]}},{label:"Ví dụ: Số giá trị khác nhau trong mỗi cửa sổ",input:"",code:"#include <iostream>\n#include <string>\n#include <unordered_map>\nusing namespace std;\n\nint main() {\n    int a[8] = {1, 2, 1, 3, 4, 2, 3, 3};\n    int n = 8, k = 4, khac = 0;\n    unordered_map<int, int> dem;\n    for (int i = 0; i < n; i++) {\n        if (dem[a[i]]++ == 0) khac++;               // thêm a[i]\n        if (i >= k && --dem[a[i - k]] == 0) khac--; // bỏ a[i - k]\n        if (i >= k - 1) cout << khac << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-k+1","i"]},{type:"cont",of:"dem"},{type:"vars",names:["khac"]}],py:{code:"a = [1, 2, 1, 3, 4, 2, 3, 3]\nn, k = len(a), 4\ndem = {}\nkhac = 0\nout = []\nfor i in range(n):\n    dem[a[i]] = dem.get(a[i], 0) + 1    # thêm a[i]\n    if dem[a[i]] == 1:\n        khac += 1\n    if i >= k:                          # bỏ a[i - k]\n        dem[a[i - k]] -= 1\n        if dem[a[i - k]] == 0:\n            khac -= 1\n    if i >= k - 1:\n        out.append(khac)\nprint(*out)",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-k+1","i"]},{type:"cont",of:"dem",as:"dict"},{type:"vars",names:["khac"]}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 1, 2, 1, 3, 4, 2, 3, 3 };\n        int n = a.Length, k = 4, khac = 0;\n        Dictionary<int, int> dem = new Dictionary<int, int>();\n        for (int i = 0; i < n; i++)\n        {\n            dem[a[i]] = dem.GetValueOrDefault(a[i]) + 1;               // thêm a[i]\n            if (dem[a[i]] == 1) khac++;\n            if (i >= k && --dem[a[i - k]] == 0) khac--;                // bỏ a[i - k]\n            if (i >= k - 1) Console.Write(khac + \" \");\n        }\n        Console.WriteLine();\n    }\n}",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-k+1","i"]},{type:"cont",of:"dem",as:"dict"},{type:"vars",names:["khac"]}]}},{label:"Ví dụ: k giá trị phổ biến nhất",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <unordered_map>\nusing namespace std;\n\nint main() {\n    int a[10] = {4, 1, 2, 2, 3, 1, 4, 4, 2, 4};\n    int k = 2;\n    unordered_map<int, int> dem;\n    for (int i = 0; i < 10; i++) dem[a[i]]++;\n    vector<pair<int, int>> v;            // (-số lần, giá trị): sắp tăng là đúng thứ tự cần\n    for (auto& p : dem) v.push_back({-p.second, p.first});\n    sort(v.begin(), v.end());\n    for (int i = 0; i < k; i++) cout << v[i].second << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"dem"},{type:"cont",of:"v"}],py:{code:"from collections import Counter\n\na = [4, 1, 2, 2, 3, 1, 4, 4, 2, 4]\nk = 2\ndem = Counter(a)\nthu_tu = sorted(dem, key=lambda v: (-dem[v], v))   # số lần giảm, giá trị tăng\nprint(*thu_tu[:k])",viz:[{type:"cont",of:"dem",as:"dict"}],note:"Counter(a) đếm sẵn. Khóa sắp xếp (−dem[v], v): số lần giảm dần, bằng nhau thì giá trị tăng dần. Kết quả 4 2. (dem.most_common(k) cũng cho k giá trị phổ biến nhất, nhưng khi bằng số lần thì giữ thứ tự gặp trước, không theo giá trị.)"},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 4, 1, 2, 2, 3, 1, 4, 4, 2, 4 };\n        int k = 2;\n        Dictionary<int, int> dem = new Dictionary<int, int>();\n        foreach (int x in a) dem[x] = dem.GetValueOrDefault(x) + 1;\n        List<int> gt = new List<int>(dem.Keys);\n        gt.Sort((x, y) => dem[x] != dem[y] ? dem[y].CompareTo(dem[x]) : x.CompareTo(y));\n        for (int i = 0; i < k; i++) Console.Write(gt[i] + \" \");\n        Console.WriteLine();\n    }\n}",viz:[{type:"cont",of:"dem",as:"dict"}],note:"Sắp xếp các giá trị bằng hàm so sánh: số lần khác nhau thì nhiều hơn đứng trước (dem[y].CompareTo(dem[x])), bằng nhau thì giá trị nhỏ đứng trước. Kết quả 4 2."}},{label:"Lỗi: đếm trước rồi mới hỏi",input:"",code:"#include <iostream>\n#include <string>\n#include <unordered_map>\nusing namespace std;\n\nint main() {\n    int a[4] = {3, 1, 5, 3};\n    int X = 6;\n    unordered_map<int, int> dem;\n    long long kq = 0;\n    for (int j = 0; j < 4; j++) {\n        dem[a[j]]++;                                     // sai thứ tự: đếm trước\n        if (dem.count(X - a[j])) kq += dem[X - a[j]];\n    }\n    cout << kq << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["j"]},{type:"cont",of:"dem"},{type:"vars",names:["kq"]}],py:{code:"a = [3, 1, 5, 3]\nX = 6\ndem = {}\nkq = 0\nfor j in range(len(a)):\n    dem[a[j]] = dem.get(a[j], 0) + 1     # sai thứ tự: đếm trước\n    kq += dem.get(X - a[j], 0)\nprint(kq)",viz:[{type:"cells",of:"a",ptr:["j"]},{type:"cont",of:"dem",as:"dict"},{type:"vars",names:["kq"]}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 3, 1, 5, 3 };\n        int X = 6;\n        Dictionary<int, int> dem = new Dictionary<int, int>();\n        long kq = 0;\n        for (int j = 0; j < a.Length; j++)\n        {\n            dem[a[j]] = dem.GetValueOrDefault(a[j]) + 1;     // sai thứ tự: đếm trước\n            kq += dem.GetValueOrDefault(X - a[j]);\n        }\n        Console.WriteLine(kq);\n    }\n}",viz:[{type:"cells",of:"a",ptr:["j"]},{type:"cont",of:"dem",as:"dict"},{type:"vars",names:["kq"]}]}}];
const sim33=makeSim2(document.getElementById("sim-l33"),{id:"s33",presets:PR33});
makeEx2(document.getElementById("ex-l33"),sim33,[{t:"Đếm cặp có tổng X",d:"Đầu vào: dòng 1 là n và X (1 ≤ n ≤ 10^5, |X| ≤ 2·10^9); dòng 2 là n số nguyên (|aᵢ| ≤ 10^9). Đầu ra: số cặp chỉ số i < j với aᵢ + aⱼ = X.",tests:[{in:"7 6\n1 5 3 3 3 5 1",out:"7"},{in:"3 10\n1 2 3",out:"0"},{in:"4 4\n2 2 2 2",out:"6"},{in:"1 14\n7",out:"0"},{in:"6 0\n-1 1 0 0 -1 1",out:"5"},{in:"3 2000000000\n1000000000 1000000000 -1000000000",out:"1"}],start:"#include <iostream>\n#include <string>\n#include <unordered_map>\nusing namespace std;\n\nint main() {\n    int n;\n    long long X;\n    cin >> n >> X;\n    unordered_map<long long, long long> dem;\n    long long kq = 0;\n    for (int j = 0; j < n; j++) {\n        long long x;\n        cin >> x;\n        // hỏi trước, đếm sau\n    }\n    cout << kq << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+" 10\n"+Array.from({length:n},(_,i)=>i%11).join(" "),ns:[500,2000,8000],need:"n",limit:n=>60*n+200,why:"Thử mọi cặp là O(n²). Bảng đếm cho O(n)."},py:{start:"n, X = map(int, input().split())\na = list(map(int, input().split()))\ndem = {}\nkq = 0\nfor x in a:\n    # hỏi trước, đếm sau\n    pass\nprint(kq)",hints:["dict đếm chứa các giá trị đứng trước phần tử đang xét.","Mỗi x: cộng dem.get(X − x, 0) vào kết quả, rồi mới tăng đếm của x.","Thử mọi cặp bằng hai vòng for là O(n²)."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]);\n        long X = long.Parse(t[1]);\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        Dictionary<long, long> dem = new Dictionary<long, long>();\n        long kq = 0;\n        foreach (long x in a)\n        {\n            // hỏi trước, đếm sau\n        }\n        Console.WriteLine(kq);\n    }\n}",hints:["Dictionary đếm chứa các giá trị đứng trước phần tử đang xét.","Mỗi x: cộng dem.GetValueOrDefault(X − x) vào kết quả, rồi mới tăng đếm của x.","Số cặp tới khoảng 5·10⁹: dùng long."]}},{t:"Số giá trị khác nhau trong mỗi cửa sổ",d:"Đầu vào: dòng 1 là n và k (1 ≤ k ≤ n ≤ 10^5); dòng 2 là n số nguyên (0 ≤ aᵢ ≤ 10^9). Đầu ra: n − k + 1 số, số thứ i là số giá trị khác nhau trong đoạn a[i..i+k−1].",tests:[{in:"8 4\n1 2 1 3 4 2 3 3",out:"3 4 4 3 3"},{in:"1 1\n5",out:"1"},{in:"4 2\n7 7 7 7",out:"1 1 1"},{in:"5 5\n1 2 3 4 5",out:"5"},{in:"5 1\n1 2 3 4 5",out:"1 1 1 1 1"},{in:"4 3\n1000000000 0 1000000000 0",out:"2 2"}],start:"#include <iostream>\n#include <string>\n#include <unordered_map>\nusing namespace std;\n\nint a[100000];\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    unordered_map<int, int> dem;\n    int khac = 0;\n    // thêm a[i]; khi i >= k thì bỏ a[i - k]; từ i >= k - 1 thì in khac\n    cout << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+" "+Math.floor(n/2)+"\n"+Array.from({length:n},(_,i)=>(i*7)%101).join(" "),ns:[500,2000,8000],need:"n",limit:n=>60*n+200,why:"Đếm lại mỗi cửa sổ tốn O(n · k). Cập nhật bảng đếm khi trượt chỉ tốn O(1) mỗi bước."},py:{start:"n, k = map(int, input().split())\na = list(map(int, input().split()))\ndem = {}\nkhac = 0\nout = []\n# thêm a[i]; khi i >= k thì bỏ a[i - k]; từ i >= k - 1 thì ghi khac\nprint(*out)",hints:["Giữ dict đếm của cửa sổ, và biến khac là số giá trị có đếm > 0.","Thêm x: đếm của x thành 1 thì khac tăng. Bỏ y: đếm của y về 0 thì khac giảm.","len(set(a[i:i + k])) cho mỗi cửa sổ tốn O(k) mỗi lần: O(n · k)."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), k = int.Parse(t[1]);\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        Dictionary<int, int> dem = new Dictionary<int, int>();\n        int khac = 0;\n        StringBuilder sb = new StringBuilder();\n        // thêm a[i]; khi i >= k thì bỏ a[i - k]; từ i >= k - 1 thì ghi khac\n        Console.WriteLine(sb.ToString().TrimEnd());\n    }\n}",hints:["Giữ Dictionary đếm của cửa sổ, và biến khac là số giá trị có đếm > 0.","Thêm x: đếm của x thành 1 thì khac tăng. Bỏ y: đếm của y về 0 thì khac giảm.","Đếm lại từ đầu cho mỗi cửa sổ tốn O(n · k)."]}},{t:"k giá trị phổ biến nhất",d:"Đầu vào: dòng 1 là n và k (1 ≤ n ≤ 10^5, k không vượt quá số giá trị khác nhau); dòng 2 là n số nguyên (|aᵢ| ≤ 10^9). Đầu ra: k giá trị xuất hiện nhiều nhất, theo số lần giảm dần; cùng số lần thì giá trị nhỏ đứng trước.",tests:[{in:"10 2\n4 1 2 2 3 1 4 4 2 4",out:"4 2"},{in:"1 1\n5",out:"5"},{in:"3 3\n3 1 2",out:"1 2 3"},{in:"5 2\n-1 -1 2 2 7",out:"-1 2"},{in:"200 5\n0 1 4 9 16 8 2 15 13 13 15 2 8 16 9 4 1 0 1 4 9 16 8 2 15 13 13 15 2 8 16 9 4 1 0 1 4 9 16 8 2 15 13 13 15 2 8 16 9 4 1 0 1 4 9 16 8 2 15 13 13 15 2 8 16 9 4 1 0 1 4 9 16 8 2 15 13 13 15 2 8 16 9 4 1 0 1 4 9 16 8 2 15 13 13 15 2 8 16 9 4 1 0 1 4 9 16 8 2 15 13 13 15 2 8 16 9 4 1 0 1 4 9 16 8 2 15 13 13 15 2 8 16 9 4 1 0 1 4 9 16 8 2 15 13 13 15 2 8 16 9 4 1 0 1 4 9 16 8 2 15 13 13 15 2 8 16 9 4 1 0 1 4 9 16 8 2 15 13 13 15 2 8 16 9 4 1 0 1 4 9 16 8 2 15 13 13 15 2 8",out:"2 8 13 15 1"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <unordered_map>\nusing namespace std;\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    unordered_map<int, int> dem;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        dem[x]++;\n    }\n    vector<pair<int, int>> v;    // (-số lần, giá trị)\n    // đưa vào v, sắp xếp, in k giá trị đầu\n    cout << \"\\n\";\n    return 0;\n}",py:{start:"from collections import Counter\n\nn, k = map(int, input().split())\na = list(map(int, input().split()))\ndem = Counter(a)\n# sắp xếp các giá trị theo (-số lần, giá trị), in k giá trị đầu",hints:["Counter(a) đếm số lần mỗi giá trị.","sorted(dem, key=lambda v: (-dem[v], v)): số lần giảm dần, bằng nhau thì giá trị tăng dần.","most_common(k) giữ thứ tự gặp trước khi bằng số lần, không đúng yêu cầu “giá trị nhỏ trước”."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]), k = int.Parse(t[1]);\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        Dictionary<int, int> dem = new Dictionary<int, int>();\n        foreach (int x in a) dem[x] = dem.GetValueOrDefault(x) + 1;\n        // sắp xếp các giá trị theo số lần giảm dần, giá trị tăng dần; in k giá trị đầu\n        Console.WriteLine();\n    }\n}",hints:["Đếm bằng Dictionary, rồi chép các khóa ra List: new List<int>(dem.Keys).","Sort với hàm so sánh: số lần khác nhau thì dem[y].CompareTo(dem[x]) (giảm dần), bằng nhau thì x.CompareTo(y).","In k phần tử đầu."]}}]);

